using FVN_REGISTER.AI.Application.Abstractions;
using FVN_REGISTER.AI.Application.Configuration;
using FVN_REGISTER.AI.Infrastructure;
using FVN_REGISTER.AI.Infrastructure.Persistence;
using FVN_REGISTER.AI.Worker;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;
var builder = Host.CreateApplicationBuilder(args);
builder.Services.AddFvnAiInfrastructure(builder.Configuration);
builder.Services.AddHostedService<IngestionWorker>();
builder.Services.AddHostedService<DataEntryWorker>();
builder.Services.AddHostedService<RetentionWorker>();
builder.Services.AddHostedService<ConversationMaintenanceWorker>();
builder.Services.AddHostedService<ConnectorWorker>();
await builder.Build().RunAsync();
internal sealed class IngestionWorker(IServiceScopeFactory scopes,IOptions<AIPlatformOptions> options,ILogger<IngestionWorker> logger) : BackgroundService
{
 private readonly string workerId=$"{Environment.MachineName}:{Environment.ProcessId}:{Guid.NewGuid():N}";
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){var poll=TimeSpan.FromSeconds(Math.Clamp(options.Value.QueuePollSeconds,2,300));var concurrency=Math.Clamp(options.Value.MaximumConcurrentJobs,1,8);logger.LogInformation("FVN AI ingestion worker {WorkerId} started. Concurrency={Concurrency}, Provider={Provider}, Model={Model}, EmbeddingModel={EmbeddingModel}.",workerId,concurrency,options.Value.DefaultProvider,options.Value.Model,options.Value.EmbeddingModel);
 if(!string.Equals(options.Value.DefaultProvider,"Ollama",StringComparison.OrdinalIgnoreCase)||string.IsNullOrWhiteSpace(options.Value.Model)||string.IsNullOrWhiteSpace(options.Value.EmbeddingModel)) logger.LogWarning("AI Worker provider/model configuration is incomplete; queued ingestion jobs will not produce AI results until it is corrected.");while(!stoppingToken.IsCancellationRequested){try{using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetService<AiPlatformDbContext>();if(db is null){logger.LogWarning("AI SQL connection string is not configured; ingestion worker is idle.");await Task.Delay(poll,stoppingToken);continue;}if(!await db.Database.CanConnectAsync(stoppingToken)){logger.LogWarning("AI SQL is unavailable; ingestion worker will retry.");await Task.Delay(poll,stoppingToken);continue;}var queue=scope.ServiceProvider.GetService<ILeasedIngestionQueue>();if(queue is null){logger.LogWarning("AI ingestion queue is not registered; worker is idle.");await Task.Delay(poll,stoppingToken);continue;}await db.Database.ExecuteSqlRawAsync("EXEC ai.usp_RecoverExpiredAiIngestionLeases;",stoppingToken);var tasks=new List<Task>();for(var i=0;i<concurrency;i++){var job=await queue.ClaimAsync(workerId,600,stoppingToken);if(job is null)break;tasks.Add(ProcessAsync(job,stoppingToken));}if(tasks.Count==0)await Task.Delay(poll,stoppingToken);else await Task.WhenAll(tasks);}catch(OperationCanceledException) when(stoppingToken.IsCancellationRequested){break;}catch(Exception ex){logger.LogError(ex,"AI ingestion worker loop failed.");await Task.Delay(poll,stoppingToken);}}}
 private async Task ProcessAsync(LeasedIngestionJob job,CancellationToken cancellationToken){using var linked=CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);var processing=ProcessCoreAsync(job,linked.Token);var leaseLost=false;while(!processing.IsCompleted&&!cancellationToken.IsCancellationRequested){var delay=Task.Delay(TimeSpan.FromMinutes(2),linked.Token);if(await Task.WhenAny(processing,delay)==processing)break;try{using var renewScope=scopes.CreateScope();var db=renewScope.ServiceProvider.GetRequiredService<AiPlatformDbContext>();await db.Database.ExecuteSqlInterpolatedAsync($"EXEC ai.usp_RenewAiIngestionLease @JobId={job.JobId}, @WorkerId={workerId}, @LeaseSeconds={600}",cancellationToken);}catch(Exception ex) when(ex is not OperationCanceledException||!cancellationToken.IsCancellationRequested){leaseLost=true;logger.LogError(ex,"Could not renew AI ingestion lease for job {JobId}.",job.JobId);linked.Cancel();break;}}try{await processing;}catch(OperationCanceledException) when(leaseLost&&!cancellationToken.IsCancellationRequested){await FailAsync(job,"INGESTION_LEASE_RENEWAL_FAILED",true,cancellationToken);}}
 private async Task ProcessCoreAsync(LeasedIngestionJob job,CancellationToken cancellationToken){try{using var scope=scopes.CreateScope();var pipeline=scope.ServiceProvider.GetRequiredService<IDocumentPipeline>();var queue=scope.ServiceProvider.GetRequiredService<ILeasedIngestionQueue>();await pipeline.ProcessAsync(job.DocumentId,workerId,cancellationToken);await queue.CompleteAsync(job.JobId,workerId,"AwaitingHumanReview",cancellationToken);logger.LogInformation("AI job {JobId} produced a review candidate for document {DocumentId}.",job.JobId,job.DocumentId);}catch(OperationCanceledException) when(cancellationToken.IsCancellationRequested){throw;}catch(NotSupportedException ex){logger.LogWarning(ex,"No extractor is configured for document {DocumentId}.",job.DocumentId);await FailAsync(job,"EXTRACTOR_NOT_SUPPORTED",false,cancellationToken);}catch(InvalidDataException ex){logger.LogWarning(ex,"Invalid content in document {DocumentId}.",job.DocumentId);await FailAsync(job,"DOCUMENT_CONTENT_INVALID",false,cancellationToken);}catch(InvalidOperationException ex){logger.LogWarning(ex,"Pipeline gate failed for document {DocumentId}: {Code}",job.DocumentId,ex.Message);var retryable=ex.Message is "CLAMD_UNAVAILABLE" or "CLAMD_TIMEOUT" or "CLAMD_IO_ERROR" or "MALWARE_SCANNER_NOT_CONFIGURED";await FailAsync(job,ex.Message.Length>120?"PIPELINE_GATE_FAILED":ex.Message,retryable,cancellationToken);}catch(FileNotFoundException ex){logger.LogError(ex,"Original blob is missing for document {DocumentId}. Check that AIPlatform:StorageRoot is the same absolute path for AI.Api and AI.Worker.",job.DocumentId);await FailAsync(job,"ORIGINAL_BLOB_MISSING",false,cancellationToken);}catch(System.ComponentModel.Win32Exception ex){logger.LogError(ex,"External OCR/rasterizer executable could not be started for document {DocumentId}. Check Tesseract/pdftoppm installation and PATH.",job.DocumentId);await FailAsync(job,"OCR_TOOL_UNAVAILABLE",true,cancellationToken);}catch(TimeoutException ex){logger.LogError(ex,"Processing timed out for document {DocumentId}.",job.DocumentId);await FailAsync(job,"PROCESSING_TIMEOUT",true,cancellationToken);}catch(Exception ex){logger.LogError(ex,"Unexpected processing failure for document {DocumentId}.",job.DocumentId);await FailAsync(job,"UNEXPECTED_PIPELINE_ERROR",true,cancellationToken);}}
 private async Task FailAsync(LeasedIngestionJob job,string code,bool retryable,CancellationToken cancellationToken){using var scope=scopes.CreateScope();var queue=scope.ServiceProvider.GetRequiredService<ILeasedIngestionQueue>();try{await queue.FailAsync(job.JobId,workerId,code,retryable,cancellationToken);}catch(Exception ex){logger.LogError(ex,"Could not persist failure for job {JobId}; lease recovery will retry.",job.JobId);}}
}
